"use client"

import React, { useEffect, useState } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { ArrowLeft, Loader2, MapPin, Users, CheckCircle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'
import { instituteService } from '@/lib/institute-service'
import { getFileUrl } from '@/lib/utils'

export default function TrainerHallDetailsPage() {
  const params = useParams()
  const router = useRouter()
  const hallId = params.id as string
  const [hall, setHall] = useState<any>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const fetchHall = async () => {
      try {
        setLoading(true)
        // Since trainers don't have a direct getHallById, we fetch all and find
        const halls = await instituteService.getHalls()
        const found = halls.find(h => h.id === hallId)
        if (found) {
          setHall(found)
        } else {
          toast.error("لم يتم العثور على القاعة")
          router.push('/trainer/halls')
        }
      } catch (e) {
        toast.error("فشل تحميل تفاصيل القاعة")
      } finally {
        setLoading(false)
      }
    }
    fetchHall()
  }, [hallId, router])

  if (loading) {
    return (
      <div className="flex h-[60vh] items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    )
  }

  if (!hall) return null

  return (
    <div className="max-w-4xl mx-auto space-y-6 pb-12" dir="rtl">
      <div className="flex items-center gap-4">
        <Button variant="outline" size="sm" onClick={() => router.back()} className="gap-2">
          <ArrowLeft className="h-4 w-4" /> العودة
        </Button>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border overflow-hidden">
        <div className="relative h-64 md:h-80 w-full bg-slate-100">
          {hall.image ? (
            <img src={getFileUrl(hall.image)} alt={hall.name} className="w-full h-full object-cover" />
          ) : (
            <div className="flex h-full items-center justify-center text-slate-400">لا توجد صورة</div>
          )}
          <div className="absolute top-4 right-4 bg-white/90 backdrop-blur-sm px-4 py-1.5 rounded-full text-sm font-semibold shadow-sm">
            {hall.type}
          </div>
        </div>

        <div className="p-6 md:p-8 space-y-8">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 mb-2">{hall.name}</h1>
            {hall.location && (
              <div className="flex items-center gap-2 text-gray-500">
                <MapPin className="h-5 w-5" />
                <span>{hall.location}</span>
                {hall.locationUrl && (
                  <a href={hall.locationUrl} target="_blank" rel="noreferrer" className="text-blue-600 hover:underline text-sm ml-2">
                    (عرض على الخريطة)
                  </a>
                )}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 flex flex-col items-center justify-center text-center gap-1">
              <Users className="h-6 w-6 text-blue-600 mb-1" />
              <span className="text-sm text-gray-500">السعة</span>
              <span className="font-bold text-gray-900">{hall.capacity} شخص</span>
            </div>
            <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 flex flex-col items-center justify-center text-center gap-1">
              <div className="h-6 w-6 text-green-600 mb-1 flex items-center justify-center font-bold text-lg">$</div>
              <span className="text-sm text-gray-500">السعر</span>
              <span className="font-bold text-gray-900">{hall.pricePerHour} ريال/ساعة</span>
            </div>
          </div>

          {hall.description && (
            <div className="space-y-3">
              <h3 className="text-xl font-bold text-gray-900">وصف القاعة</h3>
              <p className="text-gray-600 leading-relaxed whitespace-pre-wrap">{hall.description}</p>
            </div>
          )}

          {hall.facilities && hall.facilities.length > 0 && (
            <div className="space-y-3">
              <h3 className="text-xl font-bold text-gray-900">المرافق والمميزات</h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {hall.facilities.map((feature: string, idx: number) => (
                  <div key={idx} className="flex items-center gap-2 text-gray-700 bg-gray-50 p-3 rounded-lg border">
                    <CheckCircle className="h-5 w-5 text-green-500 shrink-0" />
                    <span className="text-sm">
                      {feature === 'wifi' ? 'إنترنت لاسلكي (WiFi)' :
                        feature === 'projector' ? 'جهاز عرض (Projector)' :
                          feature === 'screen' ? 'شاشة عرض' :
                            feature === 'computers' ? 'أجهزة حاسوب' : feature}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
